lfs_size_t diff = 0;
lfs_cache_t *cache = NULL;
const uint8_t *buffer_ = static_cast<const uint8_t*>(buffer);
lfs_size_t remaining = size;
lfs_off_t offset = off;

while (remaining > 0) {
    // Determine which cache to use
    if (pcache && pcache->block == block && pcache->off <= offset && 
        offset < pcache->off + pcache->size) {
        cache = const_cast<lfs_cache_t*>(pcache);
    } else if (rcache && rcache->block == block && rcache->off <= offset && 
               offset < rcache->off + rcache->size) {
        cache = rcache;
    } else {
        cache = NULL;
    }

    // Calculate how much we can compare in this iteration
    lfs_size_t chunk_size = remaining;
    if (cache && cache->off <= offset) {
        lfs_size_t cache_available = cache->off + cache->size - offset;
        chunk_size = std::min(chunk_size, cache_available);
    } else {
        // No cache hit, limit by hint or a reasonable default
        chunk_size = std::min(chunk_size, hint ? hint : 64);
    }

    // Ensure we don't exceed the block boundaries
    chunk_size = std::min(chunk_size, lfs->cfg->block_size - offset);

    uint8_t temp_buffer[256]; // Temporary buffer for reading from device
    const uint8_t *data_ptr = NULL;

    if (cache && cache->off <= offset && offset + chunk_size <= cache->off + cache->size) {
        // Data is in cache
        data_ptr = &cache->buffer[offset - cache->off];
    } else {
        // Need to read from device
        lfs_size_t read_size = std::min(static_cast<lfs_size_t>(sizeof(temp_buffer)), chunk_size);
        int err = lfs_bd_read(lfs, NULL, rcache, hint, block, offset, temp_buffer, read_size);
        if (err != LFS_ERR_OK) {
            return err;
        }
        data_ptr = temp_buffer;
    }

    // Compare the data
    int result = memcmp(data_ptr, buffer_, chunk_size);
    if (result != 0) {
        // Find the first different byte for detailed comparison
        for (lfs_size_t i = 0; i < chunk_size; i++) {
            if (data_ptr[i] != buffer_[i]) {
                return (data_ptr[i] < buffer_[i]) ? LFS_CMP_LT : LFS_CMP_GT;
            }
        }
    }

    // Update pointers and counters
    buffer_ += chunk_size;
    offset += chunk_size;
    remaining -= chunk_size;

    // Handle block boundary crossing
    if (offset >= lfs->cfg->block_size) {
        block++;
        offset = 0;
    }
}

return LFS_CMP_EQ;

